def tokenize(input_string):
    tokens = []
    current_token = ""
    i = 0
    while i < len(input_string):
        char = input_string[i]
        if char.isdigit() or (char == '.' and current_token != ''):
            current_token += char
            i += 1
        elif char in "+-*/()":
            if current_token:
                tokens.append(current_token)
                current_token = ""
            tokens.append(char)
            i += 1
        elif char.isspace():
            if current_token:
                tokens.append(current_token)
                current_token = ""
            i += 1
        else:
            raise ValueError(f"Invalid character '{char}' in input string")

    if current_token:
        tokens.append(current_token)

    return tokens

